83	// CreateDefaultContextIfMissing creates config.yaml when the current context is
84	// "default" and the file is absent, and reports whether it did. An existing
85	// config.yaml, even an invalid one, is neither read nor rewritten. The
86	// creation is exclusive, so of several concurrent callers only one gets true.
87	func CreateDefaultContextIfMissing() (bool, error) {
88		if CurrentContextName() != "default" {
89			return false, nil
90		}
91		path, err := GetContextPath("default")
92		if err != nil {
93			return false, err
94		}
95		err = createContextFile(path, newContextConfig())
96		switch {
97		case err == nil:
98			return true, nil
99		case errors.Is(err, os.ErrExist):
100			return false, nil
101		default:
102			return false, err
103		}
